CREATE TABLE settings (key text PRIMARY KEY, value text NOT NULL);
CREATE TABLE groups (id bigint PRIMARY KEY,name text,platform text,subscription_type text DEFAULT 'standard',rate_multiplier numeric DEFAULT 1,status text DEFAULT 'active',is_exclusive boolean DEFAULT false,deleted_at timestamptz,image_price_1k numeric,image_price_2k numeric,image_price_4k numeric,models_list_config jsonb DEFAULT '{}');
CREATE TABLE channels (id bigint PRIMARY KEY,name text,status text DEFAULT 'active',model_mapping jsonb DEFAULT '{}');
CREATE TABLE channel_groups (id bigint PRIMARY KEY,channel_id bigint,group_id bigint);
CREATE TABLE channel_model_pricing (id bigint PRIMARY KEY,channel_id bigint,platform text,models jsonb,billing_mode text DEFAULT 'token',input_price numeric,output_price numeric,cache_write_price numeric,cache_read_price numeric,image_output_price numeric,per_request_price numeric);
CREATE TABLE channel_pricing_intervals (id bigint PRIMARY KEY,pricing_id bigint,min_tokens integer,max_tokens integer,tier_label text,input_price numeric,output_price numeric,cache_write_price numeric,cache_read_price numeric,per_request_price numeric,sort_order integer DEFAULT 0);
CREATE TABLE usage_logs (group_id bigint,created_at timestamptz,input_tokens bigint,cache_creation_tokens bigint,cache_read_tokens bigint);
CREATE TABLE channel_monitors (id bigint PRIMARY KEY,name text,provider text,group_name text,primary_model text,extra_models jsonb,enabled boolean,api_key_encrypted text);
CREATE TABLE channel_monitor_histories (id bigint PRIMARY KEY,monitor_id bigint,model text,status text,latency_ms integer,ping_latency_ms integer,checked_at timestamptz,message text);
CREATE TABLE channel_monitor_v2_config (id integer PRIMARY KEY,enabled boolean,platforms jsonb,group_ids bigint[],health_thresholds jsonb,ignored_error_categories text[]);
CREATE TABLE channel_monitor_v2_watermarks (id integer PRIMARY KEY,usage_coverage_start timestamptz,error_coverage_start timestamptz,data_through timestamptz,last_successful_at timestamptz);
CREATE TABLE channel_monitor_v2_metrics_rollup (bucket_seconds integer,bucket_start timestamptz,platform text,group_id bigint,model text,success_requests bigint,error_requests bigint,input_tokens bigint,cache_creation_tokens bigint,cache_read_tokens bigint,ttft_sum_ms bigint,ttft_count bigint);
CREATE TABLE channel_monitor_v2_latency_histograms_rollup (bucket_seconds integer,bucket_start timestamptz,platform text,group_id bigint,model text,user_id bigint,metric text,upper_bound_ms bigint,sample_count bigint);
CREATE TABLE channel_monitor_v2_error_metrics_rollup (bucket_seconds integer,bucket_start timestamptz,platform text,group_id bigint,model text,error_category text,error_requests bigint);
CREATE TABLE accounts (id bigint PRIMARY KEY,credentials text,status text);
CREATE TABLE users (id bigint PRIMARY KEY,email text);
